PhaseManager.transition_to_phase(9)
return int(GameState.get_current_phase())

var H = load("res://tests/helpers/sm11e_m2b_scen.gd")
H.frame(16, 45, 1.3)
var cc = tree.root.get_node("Main").charge_controller
var out = []
for i in range(cc.unit_selector.get_item_count()):
	out.append(str(cc.unit_selector.get_item_metadata(i)))
print("[sm11e death blow] charge list: ", out)
return out.find("U_TERMINATOR_SQUAD_A")

var ul = tree.root.get_node("Main/HUD_Right/VBoxContainer/ChargeScrollContainer/ChargePanel/ChargeUnitSelector")
ul.get_v_scroll_bar().value = ul.get_v_scroll_bar().max_value
return true

var H = load("res://tests/helpers/sm11e_m2b_scen.gd")
var d = H.dice("charge_roll")
return int(d.get("charge_bonus", 0)) == 1 and int(d.get("total", 0)) == int(d.rolls[0]) + int(d.rolls[1]) + 1
